-- A-Level Politics Flashcards — AQA (7152)
-- Generated for the RAG Learning study app from the notes and question banks.
-- One INSERT per topic. card_order restarts at 1 within each topic.
--
-- SAFE TO RE-RUN: the DELETE below clears any previous Politics/AQA/alevel
-- rows first, so running this file twice does not duplicate cards.

-- ---------------------------------------------------------------
-- Schema: add 'level' column if not present (idempotent).
-- Politics is A-Level only, so every row below is level = 'alevel'.
-- ---------------------------------------------------------------
ALTER TABLE flashcards ADD COLUMN IF NOT EXISTS level TEXT DEFAULT 'alevel'
  CHECK (level IN ('gcse','as','alevel'));

-- ---------------------------------------------------------------
-- Clear any existing Politics cards so this file is re-runnable.
-- ---------------------------------------------------------------
DELETE FROM flashcards
 WHERE subject = 'Politics' AND exam_board = 'AQA' AND level = 'alevel';


