-- ---------------------------------------------------------------
-- VERIFY (read-only). Expect 32 rows, 256 cards in total.
-- ---------------------------------------------------------------
SELECT topic_id, topic_name, count(*) AS cards
  FROM flashcards
 WHERE subject = 'Politics' AND exam_board = 'AQA' AND level = 'alevel'
 GROUP BY topic_id, topic_name
 ORDER BY split_part(topic_id, '.', 1)::int, split_part(topic_id, '.', 2)::int;
